<?php
require_once __DIR__.'/app/lib/Db.php';
require_once __DIR__.'/app/lib/Security.php';
require_once __DIR__.'/app/lib/ProductFollows.php';
Security::start();
$user=Security::user();
if(!$user){header('Location: /login?next='.rawurlencode('/my-followed-products'));exit;}
$rows=ProductFollows::listForUser(Db::pdo(),(int)$user['id'],100);
$csrf=Security::csrf();
function mfp_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function mfp_date($v){if(!$v)return 'Not yet';$ts=strtotime((string)$v);return $ts?date('M j, Y', $ts):'Not yet';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>My Followed Products | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;margin:0;background:#f7f9fc;color:#172033}.wrap{max-width:1080px;margin:34px auto;padding:0 20px}.head{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.head a{color:#123b67}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:18px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:18px}.meta{color:#64748b;font-size:13px;line-height:1.5}.title{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.title h2{margin:0 0 4px;font-size:20px}.title a{color:#123b67;text-decoration:none}.pref{display:flex;gap:10px;align-items:flex-start;margin:18px 0 10px;padding:12px;border-radius:12px;background:#f8fafc}.pref input{margin-top:3px}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:14px}.actions a,.actions button{padding:9px 12px;border-radius:9px;font-weight:700;text-decoration:none}.actions a{background:#123b67;color:#fff}.actions button{background:#fff;color:#991b1b;border:1px solid #fecaca;cursor:pointer}.status{font-size:12px;color:#64748b}.empty{margin-top:18px;background:#fff;border:1px dashed #cbd5e1;border-radius:16px;padding:26px}.empty a{display:inline-block;margin-top:8px;padding:10px 14px;border-radius:10px;background:#123b67;color:#fff;text-decoration:none;font-weight:700}.note{margin-top:22px;padding:14px;border-radius:12px;background:#eef6fa;color:#475569;font-size:13px;line-height:1.55}@media(max-width:760px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="head"><div><h1>My Followed Products</h1><p class="meta">Manage the products you follow and whether you want community discussion emails for each one.</p></div><a href="/my-consultations">My Consultations</a></div><?php if(!$rows):?><section class="empty"><h2>You are not following any products yet</h2><p>Open a software profile and choose <strong>Follow product</strong> to receive meaningful verified product-update emails.</p><a href="/software">Browse software</a></section><?php else:?><section class="grid"><?php foreach($rows as $r):?><article class="card" data-follow-card="<?=mfp_e($r['slug'])?>"><div class="title"><div><h2><a href="/software/<?=mfp_e($r['slug'])?>"><?=mfp_e($r['name'])?></a></h2><div class="meta"><?=mfp_e($r['vendor_name']?:'Vendor not listed')?><?=!empty($r['category_name'])?' · '.mfp_e($r['category_name']):''?></div></div></div><p class="meta">Followed <?=mfp_e(mfp_date($r['followed_at']))?> · Last product-update email <?=mfp_e(mfp_date($r['last_notified_at']))?> · Product last reviewed <?=mfp_e(mfp_date($r['last_reviewed_at']))?></p><label class="pref"><input type="checkbox" data-community-toggle <?=((int)$r['community_notifications']===1)?'checked':''?>><span><strong>Community emails</strong><br><span class="meta">Email me about new community questions and replies for this product.</span></span></label><div class="actions"><a href="/software/<?=mfp_e($r['slug'])?>">View product</a><button type="button" data-unfollow>Unfollow</button><span class="status" data-status></span></div></article><?php endforeach;?></section><?php endif;?><div class="note">Product-follow and community engagement signals are retention features only. They do not affect TechSelectAI Fit Score, product evidence, recommendation ranking, or vendor placement.</div></main><script>
(()=>{const csrf=<?=json_encode($csrf,JSON_UNESCAPED_SLASHES)?>;const cards=[...document.querySelectorAll('[data-follow-card]')];const request=async(slug,method,body)=>{const r=await fetch('/api/product_follows.php?slug='+encodeURIComponent(slug),{method,credentials:'same-origin',headers:{'X-CSRF-Token':csrf,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'request_failed');return d};cards.forEach(card=>{const slug=card.dataset.followCard,toggle=card.querySelector('[data-community-toggle]'),unfollow=card.querySelector('[data-unfollow]'),status=card.querySelector('[data-status]');toggle?.addEventListener('change',async()=>{const desired=toggle.checked;toggle.disabled=true;status.textContent='Saving…';try{await request(slug,'PATCH',{community_notifications:desired});status.textContent='Saved';}catch{toggle.checked=!desired;status.textContent='Could not save preference';}finally{toggle.disabled=false;setTimeout(()=>status.textContent='',2500);}});unfollow?.addEventListener('click',async()=>{if(!confirm('Stop following this product?'))return;unfollow.disabled=true;status.textContent='Updating…';try{await request(slug,'DELETE');card.remove();if(!document.querySelector('[data-follow-card]'))location.reload();}catch{status.textContent='Could not unfollow';unfollow.disabled=false;}});});})();
</script></body></html>
